// ---------------------------------------------------------------------------
// Lookup helpers
// ---------------------------------------------------------------------------

/**
 * Look up a piece's display name by slot id + piece id.
 * Linear search through all categories.
 */
export function clothingName(part: EquipPart, pieceId: number): string {
  if (pieceId === 0) return "";
  for (const [, byId] of Object.entries(CLOTHING_CATALOG)) {
    const piece = byId[pieceId];
    if (piece && piece.装備部位.includes(part)) return piece.名前;
  }
  return "";
}

/**
 * Reverse-lookup: find a piece's id by slot id + display name.
 */
export function clothingIdByName(
  part: EquipPart,
  pieceName: string,
): number | undefined {
  for (const [, byId] of Object.entries(CLOTHING_CATALOG)) {
    for (const [idStr, piece] of Object.entries(byId)) {
      if (piece.装備部位.includes(part) && piece.名前 === pieceName) return Number(idStr);
    }
  }
  return undefined;
}

/**
 * (P3) Look up a piece by category name (ERB descriptor).
 */
export function clothingPieceByCategory(
  category: string,
  pieceId: number,
): ClothingPiece | undefined {
  return CLOTHING_CATALOG[category]?.[pieceId];
}
